def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    v3 = vars["v3"]
    value = (v1 + v2 + v3) / 3
    return {
        "value": value,
        "trace": {
            "settlements_2011": v1,
            "settlements_2012": v2,
            "settlements_2013": v3,
            "sum": v1 + v2 + v3,
            "count": 3,
            "output_meta": {
                "currency": "USD",
                "scale": "millions",
                "unit": "currency"
            }
        }
    }
